<PageTitle>ShipmentTracker - Logistics Made Simple</PageTitle>

<div class="text-center py-5">
    <h1 class="display-4 mb-3">📦 ShipmentTracker</h1>
    <p class="lead text-muted mb-4">Fast, reliable shipment tracking for your logistics needs.</p>

    <div class="card mx-auto shadow-sm" style="max-width: 500px;">
        <div class="card-body p-4">
            <h5 class="card-title mb-3">Track Your Shipment</h5>
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-00001)"
                       @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
            </div>
        </div>
    </div>

    <div class="row mt-5 justify-content-center">
        <div class="col-md-3 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h2>🚚</h2>
                    <h6>Real-Time Tracking</h6>
                    <p class="text-muted small">Monitor your shipments from origin to destination.</p>
                </div>
            </div>
        </div>
        <div class="col-md-3 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h2>📋</h2>
                    <h6>Dispatch Management</h6>
                    <p class="text-muted small">Create and manage shipments with ease.</p>
                </div>
            </div>
        </div>
        <div class="col-md-3 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h2>🔔</h2>
                    <h6>Status Updates</h6>
                    <p class="text-muted small">Stay informed at every step of delivery.</p>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Inject] private NavigationManager Navigation { get; set; } = default!;

    private string trackingNumber = string.Empty;

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            Navigation.NavigateTo($"/track/{trackingNumber.Trim()}");
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            TrackShipment();
        }
    }
}

