@page "/track"
@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h3 class="mb-4">🔍 Track Your Shipment</h3>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number"
                   @bind="searchTracking" @bind:event="oninput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment">Track</button>
        </div>
    </div>
</div>

@if (isLoading)
{
    <p><em>Loading...</em></p>
}
else if (notFound)
{
    <div class="alert alert-warning">
        <strong>Not Found.</strong> No shipment found with tracking number "<strong>@searchTracking</strong>".
    </div>
}
else if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header bg-primary text-white">
