 @code {
     [Parameter] public string? TrackingNumber { get; set; }

     private string searchTracking = string.Empty;
     private Shipment? shipment;
     private bool isLoading;
     private bool notFound;

     private readonly ShipmentStatus[] statusSteps = [
         ShipmentStatus.Pending,
         ShipmentStatus.InTransit,
         ShipmentStatus.OutForDelivery,
         ShipmentStatus.Delivered
     ];

     protected override async Task OnParametersSetAsync()
     {
         if (!string.IsNullOrWhiteSpace(TrackingNumber))
         {
             searchTracking = TrackingNumber;
             await SearchShipment();
         }
     }

     private async Task SearchShipment()
     {
         if (string.IsNullOrWhiteSpace(searchTracking)) return;

         isLoading = true;
         notFound = false;
         shipment = null;

         shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchTracking.Trim());
         notFound = shipment is null;
         isLoading = false;
     }

     private void HandleKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
         {
             _ = SearchShipment();
         }
     }

     private static int GetStepIndex(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => 0,
         ShipmentStatus.InTransit => 1,
         ShipmentStatus.OutForDelivery => 2,
         ShipmentStatus.Delivered => 3,
         _ => -1
     };

     private static string GetStepIcon(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "📋",
         ShipmentStatus.InTransit => "🚚",
         ShipmentStatus.OutForDelivery => "📬",
         ShipmentStatus.Delivered => "✅",
         _ => "❓"
     };

     private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "bg-secondary",
         ShipmentStatus.InTransit => "bg-info",
         ShipmentStatus.OutForDelivery => "bg-warning text-dark",
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.Cancelled => "bg-danger",
         _ => "bg-secondary"
     };
 }

